2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keepwell — Bookmark prototype</title>
7	  <style>
8	    :root {
9	      color-scheme: light;
10	      --ink: #1f2721;
11	      --muted: #667069;
12	      --paper: #f7f5ef;
13	      --card: #fffefa;
14	      --line: #dcded5;
15	      --green: #315a43;
16	      --green-deep: #254635;
17	      --soft-green: #e4eee7;
18	      --orange: #d8783a;
19	    }
20	    * { box-sizing: border-box; }
21	    body {
22	      margin: 0;
23	      min-height: 100vh;
24	      background: var(--paper);
25	      color: var(--ink);
26	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
27	    }
28	    .shell { min-height: 100vh; display: grid; grid-template-columns: 248px 1fr; }
29	    aside {
30	      padding: 32px 24px;
31	      border-right: 1px solid var(--line);
32	      background: #eeefe8;
33	    }
34	    .brand { display: flex; align-items: center; gap: 11px; font-weight: 750; font-size: 20px; letter-spacing: -0.02em; }
35	    .brand-mark {
36	      width: 32px; height: 32px; border-radius: 10px; background: var(--green);
37	      display: grid; place-items: center; color: white; font-family: Georgia, serif; font-size: 21px;
38	    }
39	    nav { margin-top: 52px; }
40	    .nav-label { color: #8a918b; font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; margin: 0 10px 10px; }
41	    .nav-item { display: flex; gap: 12px; align-items: center; padding: 11px 12px; border-radius: 9px; font-weight: 650; background: #dde6df; color: var(--green-deep); }
42	    .nav-icon { font-size: 18px; }
43	    main { width: min(930px, calc(100vw - 248px)); margin: 0 auto; padding: 48px 56px 80px; }
44	    header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 34px; }
45	    h1 { font-family: Georgia, "Times New Roman", serif; font-size: 38px; line-height: 1.1; margin: 0; letter-spacing: -0.025em; font-weight: 600; }
46	    .subhead { margin: 9px 0 0; color: var(--muted); font-size: 15px; }
47	    .save-panel {
48	      background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 24px;
49	      box-shadow: 0 10px 35px rgba(36, 52, 42, .05);
50	    }
51	    label { display: block; font-weight: 700; margin-bottom: 10px; font-size: 14px; }
52	    .url-row { display: grid; grid-template-columns: 1fr auto; gap: 10px; }
53	    input {
54	      width: 100%; border: 1px solid #c9cec7; border-radius: 10px; padding: 13px 14px;
55	      font: inherit; color: var(--ink); background: white; outline: none;
56	    }
57	    input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(49, 90, 67, .13); }
58	    button {
59	      border: 0; border-radius: 10px; background: var(--green); color: white; padding: 0 20px;
60	      font: inherit; font-weight: 750; cursor: pointer; min-height: 46px;
61	    }
62	    button:hover { background: var(--green-deep); }
63	    button:disabled { opacity: .65; cursor: wait; }
64	    .hint { color: var(--muted); font-size: 13px; margin: 10px 0 0; }
65	    .section-head { display: flex; justify-content: space-between; align-items: baseline; margin: 34px 0 14px; }
66	    h2 { font-size: 18px; margin: 0; }
67	    .count { color: var(--muted); font-size: 13px; }
68	    .empty {
69	      border: 1px dashed #cbd0c7; min-height: 230px; border-radius: 14px; display: grid; place-items: center;
70	      text-align: center; color: var(--muted); background: rgba(255,255,255,.35); padding: 30px;
71	    }
72	    .empty-icon { display: block; margin: 0 auto 14px; width: 44px; height: 44px; border-radius: 50%; background: var(--soft-green); color: var(--green); font-size: 22px; line-height: 44px; }
73	    .empty strong { color: var(--ink); display: block; margin-bottom: 5px; }
74	    .bookmark {
75	      display: none; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 20px;
76	      grid-template-columns: 50px 1fr auto; align-items: start; gap: 16px; box-shadow: 0 7px 24px rgba(36,52,42,.045);
77	    }
78	    .bookmark.visible { display: grid; animation: arrive .35s ease-out; }
79	    @keyframes arrive { from { opacity: 0; transform: translateY(7px); } }
80	    .site-icon { width: 50px; height: 50px; border-radius: 12px; background: #181818; color: white; display: grid; place-items: center; font-family: Georgia, serif; font-weight: 700; font-size: 23px; }
81	    .bookmark h3 { margin: 1px 0 7px; font-size: 17px; }
82	    .bookmark p { color: var(--muted); margin: 0 0 12px; font-size: 14px; line-height: 1.45; max-width: 580px; }
83	    .domain { font-size: 12px; color: #7a827c; }
84	    .saved { color: var(--green); background: var(--soft-green); border-radius: 999px; padding: 5px 9px; font-size: 12px; font-weight: 750; white-space: nowrap; }
85	    .toast { position: fixed; right: 28px; bottom: 28px; background: var(--green-deep); color: white; border-radius: 10px; padding: 12px 16px; font-size: 14px; opacity: 0; transform: translateY(8px); pointer-events: none; transition: .2s; }
86	    .toast.show { opacity: 1; transform: translateY(0); }
87	    @media (max-width: 760px) {
88	      .shell { grid-template-columns: 1fr; }
89	      aside { display: none; }
90	      main { width: 100%; padding: 28px 20px; }
91	      .url-row { grid-template-columns: 1fr; }
92	      button { min-height: 46px; }
93	    }
94	  </style>
95	</head>
96	<body>
97	  <div class="shell">
98	    <aside aria-label="Main navigation">
99	      <div class="brand"><span class="brand-mark">K</span> Keepwell</div>
100	      <nav>
101	        <p class="nav-label">Library</p>
102	        <div class="nav-item"><span class="nav-icon">⌂</span> All bookmarks</div>
103	      </nav>
104	    </aside>
105	    <main data-harness-ready="true">
106	      <header>
107	        <div>
108	          <h1>Your bookmarks</h1>
109	          <p class="subhead">A place for links worth finding again.</p>
110	        </div>
111	      </header>
112	
113	      <section class="save-panel" aria-labelledby="save-title">
114	        <label id="save-title" for="url">Save a new bookmark</label>
115	        <div class="url-row">
116	          <input id="url" type="url" value="https://www.seriouseats.com/the-food-lab-5118015" aria-describedby="url-hint">
117	          <button id="save" type="button">Save bookmark</button>
118	        </div>
119	        <p class="hint" id="url-hint">Paste a page address and Keepwell will fill in the useful details.</p>
120	      </section>
121	
122	      <div class="section-head">
123	        <h2>All bookmarks</h2>
124	        <span class="count" id="count">0 bookmarks</span>
125	      </div>
126	
127	      <div class="empty" id="empty">
128	        <div><span class="empty-icon">↗</span><strong>No bookmarks yet</strong>Your saved links will appear here with details you can recognize.</div>
129	      </div>
130	
131	      <article class="bookmark" id="bookmark" aria-live="polite">
132	        <div class="site-icon">SE</div>
133	        <div>
134	          <h3>The Food Lab: Better Home Cooking Through Science</h3>
135	          <p>Explore practical cooking techniques, tested recipes, and the science behind better results in the kitchen.</p>
136	          <span class="domain">seriouseats.com</span>
137	        </div>
138	        <span class="saved">Saved</span>
139	      </article>
140	    </main>
141	  </div>
142	  <div class="toast" id="toast" role="status">Bookmark saved with page details</div>
143	  <script>
144	    const saveButton = document.querySelector('#save');
145	    const urlInput = document.querySelector('#url');
146	    const empty = document.querySelector('#empty');
147	    const bookmark = document.querySelector('#bookmark');
148	    const count = document.querySelector('#count');
149	    const toast = document.querySelector('#toast');
150	
151	    saveButton.addEventListener('click', () => {
152	      if (!urlInput.value.trim()) { urlInput.focus(); return; }
153	      saveButton.disabled = true;
154	      saveButton.textContent = 'Getting details…';
155	      window.setTimeout(() => {
156	        empty.hidden = true;
157	        bookmark.classList.add('visible');
158	        count.textContent = '1 bookmark';
159	        saveButton.textContent = 'Saved';
160	        toast.classList.add('show');
161	        window.setTimeout(() => toast.classList.remove('show'), 2400);
162	      }, 650);
163	    });
164	  </script>
165	</body>
166	</html>
