73	    <main data-harness-ready="true">
74	      <header><h1>Your bookmarks</h1><p class="subhead">A place for links worth finding again.</p></header>
75	      <section class="save-panel" aria-label="Save a new bookmark">
76	        <label for="url">Save a new bookmark</label>
77	        <div class="url-row"><input id="url" type="url" placeholder="Paste a page address"><button class="primary" type="button" disabled>Save bookmark</button></div>
78	        <p class="hint">Paste a page address and Keepwell will fill in the useful details.</p>
79	      </section>
80	      <div class="section-head"><h2>All bookmarks</h2><span class="count">1 bookmark</span></div>
81	      <article class="bookmark" id="bookmark">
82	        <div class="site-icon">SE</div>
83	        <div class="bookmark-copy">
84	          <h3 id="shown-title">The Food Lab: Better Home Cooking Through Science</h3>
85	          <p id="shown-description">Explore practical cooking techniques, tested recipes, and the science behind better results in the kitchen.</p>
86	          <span class="domain">seriouseats.com</span>
87	        </div>
88	        <button class="edit-btn" id="edit" type="button">✎ Edit details</button>
89	        <form class="editor inline-editor" id="inline-form">
90	          <div class="field"><label for="inline-title">Title</label><input id="inline-title" name="title" value="The Food Lab: Better Home Cooking Through Science"></div>
91	          <div class="field"><label for="inline-description">Description</label><textarea id="inline-description" name="description">Explore practical cooking techniques, tested recipes, and the science behind better results in the kitchen.</textarea></div>
92	          <div class="actions"><button class="secondary cancel" type="button">Cancel</button><button class="primary" type="submit">Save changes</button></div>
93	        </form>
94	      </article>
95	    </main>
