116	  <script>
117	    const mode = new URLSearchParams(location.search).get('mode') || 'inline';
118	    const bookmark = document.querySelector('#bookmark');
119	    const modalWrap = document.querySelector('#modal-wrap');
120	    const drawerWrap = document.querySelector('#drawer-wrap');
121	    const edit = document.querySelector('#edit');
122	    const title = document.querySelector('#shown-title');
123	    const description = document.querySelector('#shown-description');
124	    const toast = document.querySelector('#toast');
125	
126	    const closeEditors = () => {
127	      bookmark.classList.remove('editing');
128	      modalWrap.classList.remove('open');
129	      drawerWrap.classList.remove('open');
130	    };
131	    edit.addEventListener('click', () => {
132	      if (mode === 'modal') {
133	        modalWrap.classList.add('open');
134	        document.querySelector('#modal-name').focus();
135	      } else if (mode === 'drawer') {
136	        drawerWrap.classList.add('open');
137	        document.querySelector('#drawer-name').focus();
138	      } else {
139	        bookmark.classList.add('editing');
140	        document.querySelector('#inline-title').focus();
141	      }
142	    });
143	    document.querySelectorAll('.cancel').forEach(button => button.addEventListener('click', closeEditors));
144	    document.querySelectorAll('form.editor, #modal-form, #drawer-form').forEach(form => form.addEventListener('submit', event => {
145	      event.preventDefault();
146	      title.textContent = new FormData(form).get('title');
147	      description.textContent = new FormData(form).get('description');
148	      closeEditors();
149	      toast.classList.add('show');
150	      window.setTimeout(() => toast.classList.remove('show'), 2200);
151	    }));
152	  </script>
