112	      <div class="field"><label for="drawer-name">Title</label><input id="drawer-name" name="title" value="The Food Lab: Better Home Cooking Through Science"></div>
113	      <div class="field"><label for="drawer-description">Description</label><textarea id="drawer-description" name="description">Explore practical cooking techniques, tested recipes, and the science behind better results in the kitchen.</textarea></div>
114	      <div class="actions"><button class="secondary cancel" type="button">Cancel</button><button class="primary" type="submit">Save changes</button></div>
115	    </form>
116	  </div>
117	  <div class="toast" id="toast" role="status">Bookmark details updated</div>
118	  <script>
119	    const mode = new URLSearchParams(location.search).get('mode') || 'inline';
120	    const bookmark = document.querySelector('#bookmark');
121	    const modalWrap = document.querySelector('#modal-wrap');
122	    const drawerWrap = document.querySelector('#drawer-wrap');
123	    const edit = document.querySelector('#edit');
124	    const title = document.querySelector('#shown-title');
125	    const description = document.querySelector('#shown-description');
126	    const toast = document.querySelector('#toast');
127	
128	    const closeEditors = () => {
129	      bookmark.classList.remove('editing');
130	      modalWrap.classList.remove('open');
131	      drawerWrap.classList.remove('open');
132	    };
133	    edit.addEventListener('click', () => {
134	      if (mode === 'modal') {
135	        modalWrap.classList.add('open');
136	        document.querySelector('#modal-name').focus();
137	      } else if (mode === 'drawer') {
138	        drawerWrap.classList.add('open');
139	        document.querySelector('#drawer-name').focus();
140	      } else {
141	        bookmark.classList.add('editing');
142	        document.querySelector('#inline-title').focus();
143	      }
144	    });
145	    document.querySelectorAll('.cancel').forEach(button => button.addEventListener('click', closeEditors));
146	    document.querySelectorAll('form.editor, #modal-form, #drawer-form').forEach(form => form.addEventListener('submit', event => {
147	      event.preventDefault();
148	      const titleInput=form.querySelector('[name="title"]');
149	      form.querySelectorAll('.field-error').forEach(message=>message.remove());
150	      titleInput.classList.remove('invalid');
151	      if(!titleInput.value.trim()){
152	        titleInput.classList.add('invalid');
153	        const message=document.createElement('p');message.className='field-error';message.textContent='Add a title so you can recognize this bookmark later.';titleInput.insertAdjacentElement('afterend',message);titleInput.focus();return;
154	      }
155	      title.textContent = new FormData(form).get('title');
156	      description.textContent = new FormData(form).get('description');
157	      closeEditors();
158	      toast.classList.add('show');
159	      window.setTimeout(() => toast.classList.remove('show'), 2200);
160	    }));
161	  </script>
